local LuaClass = require("Core/LuaClass")
local UIViewModel = require("UI/UIViewModel")

local MathUtil = require("Utils/MathUtil")
local HouseLocalDef = require("Game/House/HouseLocalDef")
local HouseInfoSettingsPanelVM = LuaClass(UIViewModel)

function HouseInfoSettingsPanelVM:Ctor()
    self.CurrentRoommate = 1
    self.RoommatesList = {}
    self.PrivilegeList = {}
    self.OriginPrivilegeList = {}
    self.Privilege = _G.HouseInfoMgr:GetHouseRoomatesPermission()
end 

function HouseInfoSettingsPanelVM:UpdateRoommates()
    for i = 1,#self.RoommatesList do
        local PrivilegeTable =  MathUtil.DecodeUint(self.RoommatesList[i].Privileges)
        local TempPrivilege = table.deepcopy(self.Privilege)
        for j = 1,#PrivilegeTable do
            TempPrivilege[PrivilegeTable[j]].Selected = true
        end

        for i = #TempPrivilege, 1, -1 do
            if not TempPrivilege[i].IsShow then
                table.remove(TempPrivilege, i)
            end
        end

        table.insert(self.PrivilegeList, TempPrivilege)
    end

    self.OriginPrivilegeList = table.deepcopy(self.PrivilegeList)
    for _, v in ipairs(self.PrivilegeList) do
        for _, t in ipairs(v) do
            t["SettingVM"] = self
        end
    end
end

return HouseInfoSettingsPanelVM